/*! Minimal OpenSeadragon-compatible viewer for offline use. Provides wheel zoom and drag pan for a single image tile source. */
(function(global){
  function getElement(ref){
    if(!ref) return null;
    if(typeof ref === 'string') return document.getElementById(ref) || document.querySelector(ref);
    return ref;
  }

  function Viewer(options){
    if(!(this instanceof Viewer)) return new Viewer(options);
    const opts = options || {};
    this.element = getElement(opts.id || opts.element);
    if(!this.element) throw new Error('OpenSeadragon container not found');
    const source = opts.tileSources && opts.tileSources.url ? opts.tileSources.url : opts.tileSources;
    this.url = typeof source === 'string' ? source : '';
    this.element.classList.add('osd-lite');
    this.image = document.createElement('img');
    this.image.src = this.url;
    this.image.alt = opts.imageAlt || '';
    this.image.draggable = false;
    this.image.style.transformOrigin = '0 0';
    this.image.style.willChange = 'transform';
    this.element.innerHTML = '';
    this.element.appendChild(this.image);

    this.scale = 1;
    this.minScale = opts.minZoomLevel || 0.3;
    this.maxScale = opts.maxZoomLevel || 10;
    this.offset = { x: 0, y: 0 };
    this.isDragging = false;
    this.last = { x: 0, y: 0 };

    this.updateTransform();
    this.attachEvents();
  }

  Viewer.prototype.updateTransform = function(){
    this.image.style.transform = 'translate(' + this.offset.x + 'px, ' + this.offset.y + 'px) scale(' + this.scale + ')';
  };

  Viewer.prototype.zoomBy = function(factor){
    const next = Math.min(this.maxScale, Math.max(this.minScale, this.scale * factor));
    this.scale = next;
    this.updateTransform();
  };

  Viewer.prototype.zoomIn = function(){ this.zoomBy(1.2); };
  Viewer.prototype.zoomOut = function(){ this.zoomBy(0.8); };
  Viewer.prototype.reset = function(){ this.scale = 1; this.offset = { x: 0, y: 0 }; this.updateTransform(); };

  Viewer.prototype.attachEvents = function(){
    const self = this;
    this.element.addEventListener('wheel', function(ev){
      ev.preventDefault();
      const factor = ev.deltaY < 0 ? 1.1 : 0.9;
      self.zoomBy(factor);
    });

    this.element.addEventListener('mousedown', function(ev){
      ev.preventDefault();
      self.isDragging = true;
      self.last = { x: ev.clientX, y: ev.clientY };
    });

    window.addEventListener('mousemove', function(ev){
      if(!self.isDragging) return;
      const dx = ev.clientX - self.last.x;
      const dy = ev.clientY - self.last.y;
      self.offset.x += dx;
      self.offset.y += dy;
      self.last = { x: ev.clientX, y: ev.clientY };
      self.updateTransform();
    });

    window.addEventListener('mouseup', function(){ self.isDragging = false; });
    this.element.addEventListener('mouseleave', function(){ self.isDragging = false; });

    // Basic keyboard support
    this.element.setAttribute('tabindex', '0');
    this.element.addEventListener('keydown', function(ev){
      if(ev.key === '+') { self.zoomIn(); }
      if(ev.key === '-') { self.zoomOut(); }
      if(ev.key === '0') { self.reset(); }
    });
  };

  function factory(options){
    return new Viewer(options);
  }

  factory.VERSION = 'lite-0.1';
  factory.Viewer = Viewer;

  global.OpenSeadragon = factory;
})(window);
